/**
 * Ordered, hand-written schema migrations. Index i upgrades the database from
 * `PRAGMA user_version = i` to `i + 1`. Never edit a migration that has shipped: append a new one.
 *
 * Conventions:
 * - ids are UUIDv7 TEXT generated by the app (time-sortable), never AUTOINCREMENT.
 * - timestamps are ISO-8601 UTC TEXT (lexicographically sortable).
 * - JSON columns are TEXT.
 * - Every list/query path has an index whose trailing columns match the ORDER BY (cursor pagination).
 */
export const MIGRATIONS: readonly string[] = [
  // ---------------------------------------------------------------- v1: initial schema
  `
  CREATE TABLE agents (
    id                 TEXT PRIMARY KEY,
    name               TEXT NOT NULL,
    role               TEXT NOT NULL DEFAULT '',
    job                TEXT NOT NULL DEFAULT '',
    runtime            TEXT NOT NULL,
    model              TEXT,
    reports_to         TEXT REFERENCES agents(id) ON DELETE SET NULL,
    heartbeat_minutes  INTEGER NOT NULL,
    monthly_budget_usd REAL NOT NULL,
    permissions        TEXT NOT NULL,            -- JSON Record<PermissionKey, PermissionLevel>
    paused             INTEGER NOT NULL DEFAULT 0,
    created_at         TEXT NOT NULL
  );
  CREATE INDEX agents_reports_to ON agents(reports_to);
  CREATE INDEX agents_created ON agents(created_at, id);

  CREATE TABLE tickets (
    id                 TEXT PRIMARY KEY,
    number             INTEGER NOT NULL UNIQUE,
    title              TEXT NOT NULL,
    goal               TEXT NOT NULL,
    status             TEXT NOT NULL CHECK (status IN ('backlog','in_progress','needs_you','blocked','done')),
    agent_id           TEXT REFERENCES agents(id) ON DELETE SET NULL,
    runtime            TEXT,
    model              TEXT,
    current_session_id TEXT,                      -- no FK: sessions reference tickets (avoid a cycle)
    folder             TEXT NOT NULL,
    cost_cap_usd       REAL NOT NULL,
    cost_usd           REAL NOT NULL DEFAULT 0,
    parent_id          TEXT REFERENCES tickets(id) ON DELETE SET NULL,
    created_at         TEXT NOT NULL,
    updated_at         TEXT NOT NULL
  );
  CREATE INDEX tickets_status_updated ON tickets(status, updated_at, id);
  CREATE INDEX tickets_updated ON tickets(updated_at, id);
  CREATE INDEX tickets_agent ON tickets(agent_id);
  CREATE INDEX tickets_parent ON tickets(parent_id);

  CREATE TABLE ticket_deps (
    ticket_id     TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,
    depends_on_id TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,
    PRIMARY KEY (ticket_id, depends_on_id),
    CHECK (ticket_id <> depends_on_id)
  );
  CREATE INDEX ticket_deps_depends_on ON ticket_deps(depends_on_id);

  CREATE TABLE sessions (
    id                  TEXT PRIMARY KEY,
    ticket_id           TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,
    agent_id            TEXT REFERENCES agents(id) ON DELETE SET NULL,
    runtime             TEXT NOT NULL,
    model               TEXT,
    external_session_id TEXT,
    reason              TEXT NOT NULL,
    started_at          TEXT NOT NULL,
    ended_at            TEXT
  );
  CREATE INDEX sessions_ticket ON sessions(ticket_id, id);
  CREATE INDEX sessions_agent ON sessions(agent_id);

  CREATE TABLE runs (
    id              TEXT PRIMARY KEY,
    session_id      TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
    ticket_id       TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,
    job_id          TEXT,                         -- no FK: finished jobs may be pruned
    trigger         TEXT NOT NULL,
    status          TEXT NOT NULL,
    started_at      TEXT NOT NULL,
    ended_at        TEXT,
    tokens_in       INTEGER NOT NULL DEFAULT 0,
    tokens_out      INTEGER NOT NULL DEFAULT 0,
    cost_usd        REAL NOT NULL DEFAULT 0,
    exit_reason     TEXT,
    snapshot_before TEXT,
    snapshot_after  TEXT
  );
  CREATE INDEX runs_ticket ON runs(ticket_id, id);
  CREATE INDEX runs_session_started ON runs(session_id, started_at);
  CREATE INDEX runs_status ON runs(status);

  CREATE TABLE messages (
    seq        INTEGER PRIMARY KEY,               -- stable rowid alias, used as the FTS rowid
    id         TEXT NOT NULL UNIQUE,
    ticket_id  TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,
    run_id     TEXT REFERENCES runs(id) ON DELETE SET NULL,
    role       TEXT NOT NULL,
    author     TEXT NOT NULL,
    text       TEXT NOT NULL,
    created_at TEXT NOT NULL
  );
  CREATE INDEX messages_ticket ON messages(ticket_id, id);

  CREATE TABLE audit_events (
    id         TEXT PRIMARY KEY,
    ticket_id  TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,
    run_id     TEXT REFERENCES runs(id) ON DELETE SET NULL,
    kind       TEXT NOT NULL,
    summary    TEXT NOT NULL,
    data       TEXT,                              -- JSON object or NULL
    created_at TEXT NOT NULL
  );
  CREATE INDEX audit_events_ticket ON audit_events(ticket_id, id);

  CREATE TABLE permission_requests (
    id         TEXT PRIMARY KEY,
    ticket_id  TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,
    run_id     TEXT REFERENCES runs(id) ON DELETE SET NULL,
    agent_id   TEXT REFERENCES agents(id) ON DELETE SET NULL,
    key        TEXT NOT NULL,
    title      TEXT NOT NULL,
    detail     TEXT NOT NULL,
    provenance TEXT,
    state      TEXT NOT NULL CHECK (state IN ('pending','allowed','denied')),
    created_at TEXT NOT NULL,
    decided_at TEXT
  );
  CREATE INDEX permission_requests_ticket ON permission_requests(ticket_id, state, id);

  CREATE TABLE status_transitions (
    id         TEXT PRIMARY KEY,
    ticket_id  TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,
    from_status TEXT NOT NULL,
    to_status  TEXT NOT NULL,
    cause      TEXT NOT NULL,
    run_id     TEXT,
    note       TEXT,
    created_at TEXT NOT NULL
  );
  CREATE INDEX status_transitions_ticket ON status_transitions(ticket_id, id);

  CREATE TABLE jobs (
    id         TEXT PRIMARY KEY,
    kind       TEXT NOT NULL,
    payload    TEXT NOT NULL,                     -- JSON JobPayload
    priority   INTEGER NOT NULL,
    state      TEXT NOT NULL CHECK (state IN ('queued','running','done','failed')),
    attempts   INTEGER NOT NULL DEFAULT 0,
    run_after  TEXT NOT NULL,
    locked_by  TEXT,
    last_error TEXT,
    dedupe_key TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );
  CREATE INDEX jobs_claim ON jobs(state, priority, id);
  -- At most one *queued* job per dedupe key (a running job may coexist with a new queued one).
  CREATE UNIQUE INDEX jobs_dedupe ON jobs(dedupe_key) WHERE state = 'queued' AND dedupe_key IS NOT NULL;

  -- Full-text search over ticket title+goal and message text, in ONE index.
  -- rowid encoding keeps both sources in one table without collisions, using values that are
  -- stable across VACUUM (implicit rowids are not):
  --   ticket  -> -tickets.number   (negative)
  --   message -> messages.seq      (positive, INTEGER PRIMARY KEY)
  CREATE VIRTUAL TABLE search_fts USING fts5(
    body,
    ticket_id UNINDEXED,
    tokenize = 'unicode61 remove_diacritics 2'
  );

  CREATE TRIGGER tickets_fts_ai AFTER INSERT ON tickets BEGIN
    INSERT INTO search_fts(rowid, body, ticket_id) VALUES (-new.number, new.title || ' ' || new.goal, new.id);
  END;
  CREATE TRIGGER tickets_fts_au AFTER UPDATE OF title, goal ON tickets BEGIN
    DELETE FROM search_fts WHERE rowid = -old.number;
    INSERT INTO search_fts(rowid, body, ticket_id) VALUES (-new.number, new.title || ' ' || new.goal, new.id);
  END;
  CREATE TRIGGER tickets_fts_ad AFTER DELETE ON tickets BEGIN
    DELETE FROM search_fts WHERE rowid = -old.number;
  END;
  CREATE TRIGGER messages_fts_ai AFTER INSERT ON messages BEGIN
    INSERT INTO search_fts(rowid, body, ticket_id) VALUES (new.seq, new.text, new.ticket_id);
  END;
  CREATE TRIGGER messages_fts_au AFTER UPDATE OF text ON messages BEGIN
    DELETE FROM search_fts WHERE rowid = old.seq;
    INSERT INTO search_fts(rowid, body, ticket_id) VALUES (new.seq, new.text, new.ticket_id);
  END;
  CREATE TRIGGER messages_fts_ad AFTER DELETE ON messages BEGIN
    DELETE FROM search_fts WHERE rowid = old.seq;
  END;
  `,
  // v2 (2026-11-10): "Always allow this command" (trusted commands) + the command on permission requests.
  `
  ALTER TABLE permission_requests ADD COLUMN command TEXT;                       -- JSON CommandSpec or NULL
  ALTER TABLE permission_requests ADD COLUMN always_allowed INTEGER NOT NULL DEFAULT 0;

  CREATE TABLE trusted_commands (
    id         TEXT PRIMARY KEY,
    shell      TEXT NOT NULL,
    command    TEXT NOT NULL,
    request_id TEXT REFERENCES permission_requests(id) ON DELETE SET NULL,
    created_at TEXT NOT NULL,
    UNIQUE (shell, command)
  );
  `,
  // v3 (2026-11-10): Skills v1. Skill content lives in <workspace>/skills/<slug>/SKILL.md; only the
  // assignment to agents is stored here.
  `
  CREATE TABLE agent_skills (
    agent_id    TEXT NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
    skill_slug  TEXT NOT NULL,
    position    INTEGER NOT NULL,
    assigned_at TEXT NOT NULL,
    PRIMARY KEY (agent_id, skill_slug)
  );
  CREATE INDEX agent_skills_slug ON agent_skills(skill_slug);
  `,
  // v4 (2026-11-10): allow-once consumption as a column (it used to be tracked in memory and
  // mirrored in the audit log). Backfill from the audit markers the gate wrote before v4
  // (kind 'permission', data = {"requestId": …, "consumed": true}) so used grants stay used.
  `
  ALTER TABLE permission_requests ADD COLUMN consumed_at TEXT;

  UPDATE permission_requests
     SET consumed_at = (
       SELECT MIN(a.created_at) FROM audit_events a
        WHERE a.kind = 'permission'
          AND json_valid(a.data)
          AND json_type(a.data, '$.consumed') = 'true'
          AND json_extract(a.data, '$.requestId') = permission_requests.id)
   WHERE consumed_at IS NULL
     AND state = 'allowed'
     AND id IN (
       SELECT json_extract(a.data, '$.requestId') FROM audit_events a
        WHERE a.kind = 'permission'
          AND json_valid(a.data)
          AND json_type(a.data, '$.consumed') = 'true');
  `,
  // v5 (2026-11-11): projects (groups of tickets with a shared brief) and ticket tags.
  `
  CREATE TABLE projects (
    id          TEXT PRIMARY KEY,
    name        TEXT NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    color       TEXT NOT NULL,
    archived    INTEGER NOT NULL DEFAULT 0,
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL
  );
  CREATE UNIQUE INDEX projects_name ON projects(name COLLATE NOCASE);

  ALTER TABLE tickets ADD COLUMN project_id TEXT REFERENCES projects(id) ON DELETE SET NULL;
  CREATE INDEX tickets_project ON tickets(project_id, updated_at, id);

  CREATE TABLE ticket_tags (
    ticket_id TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,
    tag       TEXT NOT NULL,
    PRIMARY KEY (ticket_id, tag)
  );
  CREATE INDEX ticket_tags_tag ON ticket_tags(tag, ticket_id);
  `,
  // v6 (2026-11-12, v0.4, docs/28 v0.4 Plan.md): teams + routing, ticket origin, session library
  // (agent memory), tamper-evident security log, triggers (webhook / mail / schedule).
  `
  -- ---- §C teams
  CREATE TABLE teams (
    id             TEXT PRIMARY KEY,
    slug           TEXT NOT NULL,
    name           TEXT NOT NULL,
    description    TEXT NOT NULL DEFAULT '',
    color          TEXT NOT NULL,
    lead_agent_id  TEXT REFERENCES agents(id) ON DELETE SET NULL,
    routing_hints  TEXT NOT NULL DEFAULT '',
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL
  );
  CREATE UNIQUE INDEX teams_slug ON teams(slug);
  CREATE UNIQUE INDEX teams_name ON teams(name COLLATE NOCASE);

  ALTER TABLE agents ADD COLUMN team_id TEXT REFERENCES teams(id) ON DELETE SET NULL;
  CREATE INDEX agents_team ON agents(team_id);
  ALTER TABLE tickets ADD COLUMN team_id TEXT REFERENCES teams(id) ON DELETE SET NULL;
  CREATE INDEX tickets_team ON tickets(team_id, updated_at, id);

  -- ---- §D ticket origin (JSON TicketOrigin or NULL)
  ALTER TABLE tickets ADD COLUMN origin TEXT;

  -- ---- §A session library
  CREATE TABLE session_entries (
    seq                 INTEGER PRIMARY KEY,          -- stable rowid alias, used as the FTS rowid
    id                  TEXT NOT NULL UNIQUE,
    source              TEXT NOT NULL CHECK (source IN ('sebeto','claude-code')),
    external_session_id TEXT,
    session_id          TEXT REFERENCES sessions(id) ON DELETE SET NULL,
    ticket_id           TEXT REFERENCES tickets(id) ON DELETE SET NULL,
    title               TEXT NOT NULL,
    summary             TEXT NOT NULL DEFAULT '',
    category            TEXT NOT NULL DEFAULT '',
    tags                TEXT NOT NULL DEFAULT '[]',   -- JSON string[]
    cwd                 TEXT,
    file_path           TEXT,                         -- transcript file of an external session (never exposed to agents)
    file_mtime          TEXT,                         -- to skip unchanged files on rescan
    runtime             TEXT,
    model               TEXT,
    message_count       INTEGER NOT NULL DEFAULT 0,
    cost_usd            REAL NOT NULL DEFAULT 0,
    pinned              INTEGER NOT NULL DEFAULT 0,
    started_at          TEXT NOT NULL,
    last_activity_at    TEXT NOT NULL,
    created_at          TEXT NOT NULL,
    updated_at          TEXT NOT NULL
  );
  CREATE UNIQUE INDEX session_entries_external ON session_entries(source, external_session_id) WHERE external_session_id IS NOT NULL;
  CREATE UNIQUE INDEX session_entries_session ON session_entries(session_id) WHERE session_id IS NOT NULL;
  CREATE INDEX session_entries_activity ON session_entries(last_activity_at, id);
  CREATE INDEX session_entries_category ON session_entries(category, last_activity_at, id);
  CREATE INDEX session_entries_ticket ON session_entries(ticket_id);

  CREATE VIRTUAL TABLE session_fts USING fts5(
    body,
    tokenize = 'unicode61 remove_diacritics 2'
  );
  CREATE TRIGGER session_entries_fts_ai AFTER INSERT ON session_entries BEGIN
    INSERT INTO session_fts(rowid, body) VALUES (new.seq, new.title || ' ' || new.summary || ' ' || new.category || ' ' || new.tags);
  END;
  CREATE TRIGGER session_entries_fts_au AFTER UPDATE OF title, summary, category, tags ON session_entries BEGIN
    DELETE FROM session_fts WHERE rowid = old.seq;
    INSERT INTO session_fts(rowid, body) VALUES (new.seq, new.title || ' ' || new.summary || ' ' || new.category || ' ' || new.tags);
  END;
  CREATE TRIGGER session_entries_fts_ad AFTER DELETE ON session_entries BEGIN
    DELETE FROM session_fts WHERE rowid = old.seq;
  END;

  -- ---- §B security log: append-only, hash-chained. No foreign keys on purpose: deleting a ticket,
  -- agent or session must never delete its security history.
  CREATE TABLE security_events (
    seq           INTEGER PRIMARY KEY,
    id            TEXT NOT NULL UNIQUE,
    at            TEXT NOT NULL,
    category      TEXT NOT NULL,
    action        TEXT NOT NULL,
    severity      TEXT NOT NULL CHECK (severity IN ('info','notice','warning','critical')),
    actor_type    TEXT NOT NULL,
    actor_id      TEXT,
    actor_name    TEXT NOT NULL,
    ticket_id     TEXT,
    ticket_number INTEGER,
    agent_id      TEXT,
    session_id    TEXT,
    run_id        TEXT,
    summary       TEXT NOT NULL,
    data          TEXT,                               -- JSON object or NULL
    prev_hash     TEXT NOT NULL,
    hash          TEXT NOT NULL
  );
  CREATE INDEX security_events_at ON security_events(at, seq);
  CREATE INDEX security_events_category ON security_events(category, seq);
  CREATE INDEX security_events_severity ON security_events(severity, seq);
  CREATE INDEX security_events_agent ON security_events(agent_id, seq);
  CREATE INDEX security_events_ticket ON security_events(ticket_id, seq);
  CREATE INDEX security_events_session ON security_events(session_id, seq);
  CREATE TRIGGER security_events_no_update BEFORE UPDATE ON security_events BEGIN
    SELECT RAISE(ABORT, 'security_events is append-only');
  END;

  -- ---- §D triggers
  CREATE TABLE triggers (
    id                    TEXT PRIMARY KEY,
    name                  TEXT NOT NULL,
    kind                  TEXT NOT NULL CHECK (kind IN ('webhook','mail','schedule')),
    enabled               INTEGER NOT NULL DEFAULT 1,
    config                TEXT NOT NULL,              -- JSON TriggerConfig
    blueprint             TEXT NOT NULL,              -- JSON TicketBlueprint
    dedupe_window_minutes INTEGER NOT NULL DEFAULT 60,
    secret_hash           TEXT,                       -- webhook: sha256 of the secret (verify Bearer); HMAC key kept in the secret store
    state                 TEXT,                       -- JSON runtime state (mail: last seen uid; schedule: next run)
    last_fired_at         TEXT,
    fire_count            INTEGER NOT NULL DEFAULT 0,
    created_at            TEXT NOT NULL,
    updated_at            TEXT NOT NULL
  );
  CREATE TABLE trigger_fires (
    id          TEXT PRIMARY KEY,
    trigger_id  TEXT NOT NULL REFERENCES triggers(id) ON DELETE CASCADE,
    at          TEXT NOT NULL,
    outcome     TEXT NOT NULL CHECK (outcome IN ('created','commented','ignored','rejected','error')),
    ticket_id   TEXT REFERENCES tickets(id) ON DELETE SET NULL,
    dedupe_key  TEXT,
    detail      TEXT NOT NULL
  );
  CREATE INDEX trigger_fires_trigger ON trigger_fires(trigger_id, at, id);
  CREATE INDEX trigger_fires_dedupe ON trigger_fires(trigger_id, dedupe_key, at);
  `,
  // v7 (2026-11-12, v0.4 §A): "Remove from library" hides an entry instead of deleting the row, so a
  // rescan (Claude Code files) or the next ticket change (Sebeto sessions) does not bring it back.
  `
  ALTER TABLE session_entries ADD COLUMN hidden INTEGER NOT NULL DEFAULT 0;
  `,
  // v8 (2026-11-13, v0.4 F/G/E, docs/28 v0.4 Plan.md): team AI policy (runtime/model/lock), scope
  // requirement + ticket scope, memory graph index (the notes themselves are Markdown files in
  // <workspace>/memory/, Obsidian compatible; this is only an index rebuilt from them).
  `
  ALTER TABLE teams ADD COLUMN runtime TEXT;
  ALTER TABLE teams ADD COLUMN model TEXT;
  ALTER TABLE teams ADD COLUMN lock_runtime INTEGER NOT NULL DEFAULT 0;
  ALTER TABLE teams ADD COLUMN require_scope INTEGER NOT NULL DEFAULT 0;

  ALTER TABLE tickets ADD COLUMN scope TEXT;                 -- JSON TicketScope or NULL

  CREATE TABLE memory_notes (
    seq          INTEGER PRIMARY KEY,                      -- FTS rowid
    id           TEXT NOT NULL UNIQUE,
    path         TEXT NOT NULL UNIQUE,                     -- relative to <workspace>/memory, '/' separators
    title        TEXT NOT NULL,
    key          TEXT NOT NULL,                            -- normalised title (link target), see memoryKey()
    kind         TEXT NOT NULL,
    provenance   TEXT NOT NULL,
    untrusted    INTEGER NOT NULL DEFAULT 0,
    status       TEXT NOT NULL CHECK (status IN ('approved','proposed')),
    team_slug    TEXT,
    ticket_id    TEXT REFERENCES tickets(id) ON DELETE SET NULL,
    tags         TEXT NOT NULL DEFAULT '[]',
    excerpt      TEXT NOT NULL DEFAULT '',
    sha256       TEXT NOT NULL,
    file_mtime   TEXT NOT NULL,
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL
  );
  CREATE INDEX memory_notes_key ON memory_notes(key);
  CREATE INDEX memory_notes_kind ON memory_notes(kind, updated_at);
  CREATE INDEX memory_notes_team ON memory_notes(team_slug, updated_at);
  CREATE INDEX memory_notes_status ON memory_notes(status, updated_at);

  CREATE TABLE memory_links (
    from_id  TEXT NOT NULL REFERENCES memory_notes(id) ON DELETE CASCADE,
    to_key   TEXT NOT NULL,                                -- normalised target title (may have no note yet)
    PRIMARY KEY (from_id, to_key)
  );
  CREATE INDEX memory_links_to ON memory_links(to_key, from_id);

  CREATE VIRTUAL TABLE memory_fts USING fts5(
    body,
    tokenize = 'unicode61 remove_diacritics 2'
  );
  `,
  // v9 (2026-11-13, v0.5 K, docs/29 v0.5 Plan.md): who chose a session library category, so the
  // Chief of Staff's / rules' suggestions never overwrite the owner's choice. NULL = Sebeto's own
  // filing (team/tag) or none. Claude Code entries are imported without a category, so a category
  // they already have was typed by the owner. (The usual backup is taken before migrating.)
  `
  ALTER TABLE session_entries ADD COLUMN category_source TEXT CHECK (category_source IN ('owner','auto','rules'));
  UPDATE session_entries SET category_source = 'owner' WHERE source = 'claude-code' AND category <> '';
  `,
  // v10 (2026-11-14, v0.6 O): the Chief of Staff's planning calls (routing, intake chat, memory
  // notes, session categories…), one row per call, so the Costs page counts them. Never any prompt or
  // answer text: only the purpose, the ticket (when there is one), the AI, the cost and token counts.
  // Rows are kept forever (a few dozen bytes per call). The single 'tracking_started' row (cost 0)
  // marks when recording began: memory-note costs from the security log are counted only before it,
  // so nothing is counted twice. Plus the index on runs.started_at that the cost report filters by.
  `
  CREATE TABLE planning_calls (
    id          TEXT PRIMARY KEY,
    at          TEXT NOT NULL,
    purpose     TEXT NOT NULL,
    ticket_id   TEXT REFERENCES tickets(id) ON DELETE SET NULL,
    runtime     TEXT NOT NULL DEFAULT '',
    model       TEXT,
    cost_usd    REAL NOT NULL DEFAULT 0,
    tokens_in   INTEGER NOT NULL DEFAULT 0,
    tokens_out  INTEGER NOT NULL DEFAULT 0,
    ok          INTEGER NOT NULL DEFAULT 1
  );
  CREATE INDEX planning_calls_at ON planning_calls(at);
  CREATE INDEX planning_calls_ticket ON planning_calls(ticket_id);
  INSERT INTO planning_calls (id, at, purpose, runtime, cost_usd, ok)
    VALUES ('tracking-started', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), 'tracking_started', '', 0, 1);
  CREATE INDEX IF NOT EXISTS runs_started ON runs(started_at);
  `,
  // v11 (2026-11-15): "Allow for this task" — a permission grant scoped to the whole ticket (like a
  // mailbox read), not consumed after one use, so the agent isn't re-asked for the same action during
  // the task. Distinct from "always allow" (a trusted command, which spans every ticket).
  `
  ALTER TABLE permission_requests ADD COLUMN task_scoped INTEGER NOT NULL DEFAULT 0;
  `,
  // v12 (2026-11-16, docs/37 Atlassian & Slack Connectors.md): Slack channel and Jira triggers. SQLite cannot
  // change a CHECK constraint, so the two trigger tables are rebuilt with every row kept. Done
  // without turning foreign keys off (not allowed inside the migration transaction): the new
  // tables are filled first, the old ones dropped (fires before triggers), then renamed, which
  // also points trigger_fires at the new triggers table.
  `
  CREATE TABLE triggers_v12 (
    id                    TEXT PRIMARY KEY,
    name                  TEXT NOT NULL,
    kind                  TEXT NOT NULL CHECK (kind IN ('webhook','mail','schedule','slack','jira')),
    enabled               INTEGER NOT NULL DEFAULT 1,
    config                TEXT NOT NULL,
    blueprint             TEXT NOT NULL,
    dedupe_window_minutes INTEGER NOT NULL DEFAULT 60,
    secret_hash           TEXT,
    state                 TEXT,
    last_fired_at         TEXT,
    fire_count            INTEGER NOT NULL DEFAULT 0,
    created_at            TEXT NOT NULL,
    updated_at            TEXT NOT NULL
  );
  INSERT INTO triggers_v12 SELECT id, name, kind, enabled, config, blueprint, dedupe_window_minutes, secret_hash, state, last_fired_at, fire_count, created_at, updated_at FROM triggers;
  CREATE TABLE trigger_fires_v12 (
    id          TEXT PRIMARY KEY,
    trigger_id  TEXT NOT NULL REFERENCES triggers_v12(id) ON DELETE CASCADE,
    at          TEXT NOT NULL,
    outcome     TEXT NOT NULL CHECK (outcome IN ('created','commented','ignored','rejected','error')),
    ticket_id   TEXT REFERENCES tickets(id) ON DELETE SET NULL,
    dedupe_key  TEXT,
    detail      TEXT NOT NULL
  );
  INSERT INTO trigger_fires_v12 SELECT id, trigger_id, at, outcome, ticket_id, dedupe_key, detail FROM trigger_fires;
  DROP TABLE trigger_fires;
  DROP TABLE triggers;
  ALTER TABLE triggers_v12 RENAME TO triggers;
  ALTER TABLE trigger_fires_v12 RENAME TO trigger_fires;
  CREATE INDEX trigger_fires_trigger ON trigger_fires(trigger_id, at, id);
  CREATE INDEX trigger_fires_dedupe ON trigger_fires(trigger_id, dedupe_key, at);
  `,
  // v13 (2026-11-16, docs/37): agents on Claude Code may use some of the owner's Claude connectors
  // (JSON array of server names; NULL = none). Every call is still approved through Sebeto.
  `
  ALTER TABLE agents ADD COLUMN claude_connectors TEXT;
  `,
  // v14 (2026-11-16): "Deleted tickets". Deleting a ticket only sets deleted_at (it disappears from the
  // board and can be restored); "Delete forever" removes the row (children cascade) and its folder.
  `
  ALTER TABLE tickets ADD COLUMN deleted_at TEXT;
  CREATE INDEX tickets_deleted ON tickets(deleted_at, updated_at);
  `,
  // v15 (2026-11-17): the owner's Claude connectors a whole team may use (JSON array of server
  // names; NULL = none), on top of each agent's own ticks. Every call is still approved through Sebeto.
  // Agents can ask for a connector: permission_requests.connector holds what they asked for.
  `
  ALTER TABLE teams ADD COLUMN claude_connectors TEXT;
  ALTER TABLE permission_requests ADD COLUMN connector TEXT;            -- JSON ConnectorActivation or NULL
  `,
];
